import{_ as o,r as a,o as e,c,e as s,a as l,s as u}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Обработчики событий - October CMS - 3.x","titleTemplate":false,"description":"Проектируйте свой API и динамически обновляйте страницу.","frontmatter":{"subtitle":"Проектируйте свой API и динамически обновляйте страницу."},"headers":[{"level":2,"title":"AJAX-обработчики","slug":"ajax-обработчики","link":"#ajax-обработчики","children":[{"level":3,"title":"Вызов обработчика","slug":"вызов-обработчика","link":"#вызов-обработчика","children":[]},{"level":3,"title":"Сериализация формы","slug":"сериализация-формы","link":"#сериализация-формы","children":[]},{"level":3,"title":"Универсальный обработчик","slug":"универсальныи-обработчик","link":"#универсальныи-обработчик","children":[]},{"level":3,"title":"Обработчики компонентов","slug":"обработчики-компонентов","link":"#обработчики-компонентов","children":[]}]},{"level":2,"title":"Перенаправления в AJAX-обработчиках","slug":"перенаправления-в-ajax-обработчиках","link":"#перенаправления-в-ajax-обработчиках","children":[]},{"level":2,"title":"Возврат данных из AJAX-обработчиков","slug":"возврат-данных-из-ajax-обработчиков","link":"#возврат-данных-из-ajax-обработчиков","children":[]},{"level":2,"title":"Выполнение кода перед обработчиками","slug":"выполнение-кода-перед-обработчиками","link":"#выполнение-кода-перед-обработчиками","children":[]},{"level":2,"title":"Генерация AJAX-исключения","slug":"генерация-ajax-исключения","link":"#генерация-ajax-исключения","children":[]},{"level":2,"title":"Отправка событий в браузер","slug":"отправка-событии-в-браузер","link":"#отправка-событии-в-браузер","children":[]}],"relativePath":"3.x/ru/cms/ajax/handlers.md","filePath":"3.x/ru/cms/ajax/handlers.md"}'),i={name:"3.x/ru/cms/ajax/handlers.md"};function k(r,n,d,g,m,h){const t=a("pre-heading"),p=a("post-heading");return e(),c("div",null,[s(t),n[0]||(n[0]=l("h1",null,"Обработчики событий",-1)),s(p),n[1]||(n[1]=u(`<p>AJAX-обработчики событий — это конечные точки API для взаимодействия AJAX-фреймворка с сервером. Они могут отвечать необработанными данными, перенаправлять браузер или динамически обновлять фрагменты на странице.</p><h2 id="ajax-обработчики"><a href="#ajax-обработчики" class="header-anchor">#</a> AJAX-обработчики</h2><p>Чтобы создать AJAX-обработчик, определите его как PHP-функцию в PHP-секции страницы, фрагмента или макета, или <a href="./../themes/components.html">внутри CMS-компонентов</a>. Имена обработчиков должны следовать шаблону <code>onSomething</code>, например, <code>onName</code>. Все обработчики поддерживают <a href="./update-partials.html">обновление фрагментов</a> в рамках AJAX-запроса.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onSubmitContactForm</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// ...</span>
<span class="token punctuation">}</span>
</code></pre></div><div class="custom-block tip"><p>Если два обработчика с одинаковым именем определены на странице и в макете одновременно, обработчик страницы будет иметь приоритет. Обработчики, определённые в компонентах, имеют наименьший приоритет.</p></div><h3 id="вызов-обработчика"><a href="#вызов-обработчика" class="header-anchor">#</a> Вызов обработчика</h3><p>Каждый AJAX-запрос должен указывать имя обработчика, используя <a href="./../ajax/attributes-api.html">API атрибутов данных</a> или <a href="./../ajax/javascript-api.html">JavaScript API</a>. При выполнении запроса сервер просматривает все зарегистрированные обработчики и находит первый подходящий.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token comment">&lt;!-- Attributes API --&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onSubmitContactForm<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Go<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>

<span class="token comment">&lt;!-- JavaScript API --&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>script</span><span class="token punctuation">&gt;</span></span><span class="token script"><span class="token language-javascript"> oc<span class="token punctuation">.</span><span class="token function">ajax</span><span class="token punctuation">(</span><span class="token string">&#39;onSubmitContactForm&#39;</span><span class="token punctuation">)</span> </span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>script</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Обработчики, определённые страницами, макетами и компонентами, регистрируются автоматически. Если вы вызываете обработчик из фрагмента, используйте <a href="./../../markup/tag/ajax-partial.html">Twig-тег <code>{% ajaxPartial %}</code></a>, который корректирует цикл страницы для регистрации обработчиков.</p><h3 id="сериализация-формы"><a href="#сериализация-формы" class="header-anchor">#</a> Сериализация формы</h3><p>Когда AJAX-запрос происходит внутри HTML-тега формы, все значения полей ввода формы доступны обработчику. В примере ниже значение <code>first_name</code> будет отправлено вместе с запросом.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">id</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>myForm<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>first_name<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onSubmitContactForm<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Go<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>JavaScript API поддерживает эту логику с помощью функции <code>oc.request</code>.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>script</span><span class="token punctuation">&gt;</span></span><span class="token script"><span class="token language-javascript"> oc<span class="token punctuation">.</span><span class="token function">request</span><span class="token punctuation">(</span><span class="token string">&#39;#myForm&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;onSubmitContactForm&#39;</span><span class="token punctuation">)</span> </span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>script</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Вы можете использовать PHP-функцию <code>input()</code> для доступа к переменной.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onSubmitContactForm</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$firstName</span> <span class="token operator">=</span> <span class="token function">input</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;first_name&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="универсальныи-обработчик"><a href="#универсальныи-обработчик" class="header-anchor">#</a> Универсальный обработчик</h3><p>Иногда вам может потребоваться выполнить AJAX-запрос только для обновления содержимого страницы, без необходимости выполнения какого-либо кода. Для этой цели вы можете использовать обработчик <code>onAjax</code>. Этот обработчик доступен повсюду и не требует написания кода.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onAjax<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Do nothing<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h3 id="обработчики-компонентов"><a href="#обработчики-компонентов" class="header-anchor">#</a> Обработчики компонентов</h3><p>Если два компонента регистрируют обработчик с одинаковым именем, рекомендуется указывать префикс с <a href="./../../cms/themes/components.html">кратким именем или псевдонимом компонента</a>. Если компонент использует псевдоним <strong>mycomponent</strong>, обработчик может быть вызван как <code>mycomponent::onName</code>.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>mycomponent::onSubmitContactForm<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Go<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Подробнее читайте в <a href="./../../extend/cms-components.html">статье о разработке компонентов</a>.</p><h2 id="перенаправления-в-ajax-обработчиках"><a href="#перенаправления-в-ajax-обработчиках" class="header-anchor">#</a> Перенаправления в AJAX-обработчиках</h2><p>Если вам нужно перенаправить браузер на другой адрес, верните объект ответа <code>Redirect</code> из AJAX-обработчика. Фреймворк перенаправит браузер сразу после получения ответа от сервера. Пример AJAX-обработчика с перенаправлением:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onRedirectMe</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Redirect</span><span class="token operator">::</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;http://google.com&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="возврат-данных-из-ajax-обработчиков"><a href="#возврат-данных-из-ajax-обработчиков" class="header-anchor">#</a> Возврат данных из AJAX-обработчиков</h2><p>Ответ от AJAX-обработчика может служить потребляемым API, возвращая структурированные данные. Если AJAX-обработчик возвращает массив, вы можете получить доступ к его элементам в обработчике события <code>success</code>. Пример AJAX-обработчика, возвращающего объект данных:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onFetchDataFromServer</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// Some server-side code</span>

    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;totalUsers&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">1000</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;totalProjects&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">937</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Данные можно получить с помощью API атрибутов данных.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onHandleForm<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-request-success</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>console.log(data)<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>То же самое с JavaScript API.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token special-attr"><span class="token attr-name">onsubmit</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token value javascript language-javascript">oc<span class="token punctuation">.</span><span class="token function">request</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">,</span> <span class="token string">&#39;onHandleForm&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span>
        <span class="token function-variable function">success</span><span class="token operator">:</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token parameter">data</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>data<span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token keyword">return</span> <span class="token boolean">false</span></span><span class="token punctuation">&quot;</span></span></span>
<span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="выполнение-кода-перед-обработчиками"><a href="#выполнение-кода-перед-обработчиками" class="header-anchor">#</a> Выполнение кода перед обработчиками</h2><p>Иногда вам может потребоваться выполнить код перед выполнением обработчика. Определение функции <code>onInit</code> как части <a href="./../../cms/themes/layouts.html">жизненного цикла выполнения макета</a> позволяет запускать код перед каждым AJAX-обработчиком.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onInit</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// From a page or layout PHP code section</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Вы можете определить метод <code>init</code> внутри <a href="./../../extend/cms-components.html">класса CMS-компонента</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">init</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// From a component or widget class</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="генерация-ajax-исключения"><a href="#генерация-ajax-исключения" class="header-anchor">#</a> Генерация AJAX-исключения</h2><p>Вы можете сгенерировать <a href="./../../extend/system/exceptions.html">AJAX-исключение</a> с помощью класса <code>AjaxException</code>, чтобы обработать ответ как ошибку, сохранив при этом возможность отправки содержимого ответа в обычном режиме. Просто передайте содержимое ответа в качестве первого аргумента исключения.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">AjaxException</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;error&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Not enough questions&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;questionsNeeded&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">2</span>
<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Эти ошибки обрабатываются AJAX-фреймворком.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onHandleForm<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-request-error</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>console.log(data)<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>То же самое с JavaScript API.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token special-attr"><span class="token attr-name">onsubmit</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token value javascript language-javascript">oc<span class="token punctuation">.</span><span class="token function">request</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">,</span> <span class="token string">&#39;onHandleForm&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span>
        <span class="token function-variable function">error</span><span class="token operator">:</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token parameter">data</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>data<span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token keyword">return</span> <span class="token boolean">false</span></span><span class="token punctuation">&quot;</span></span></span>
<span class="token punctuation">&gt;</span></span>
</code></pre></div><div class="custom-block tip"><p>При генерации исключения этого типа <a href="./update-partials.html">фрагменты будут обновлены</a> в обычном режиме.</p></div><h2 id="отправка-событии-в-браузер"><a href="#отправка-событии-в-браузер" class="header-anchor">#</a> Отправка событий в браузер</h2><div class="custom-block aside"><p>Отправленные события вызываются в AJAX-ответе после завершения запроса и перед обновлением фрагментов.</p></div><p>Вы можете отправлять JavaScript-события из AJAX-обработчиков с помощью метода <code>dispatchBrowserEvent</code>. Этот метод принимает произвольное имя события (первый аргумент) и переменные деталей для передачи событию (второй аргумент), переменные должны быть совместимы с JSON-сериализацией.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onPerformAction</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">dispatchBrowserEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;app:update-profile&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">dispatchBrowserEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;app:update-profile&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Jeff&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>В браузере используйте <code>addEventListener</code> для прослушивания отправленного события при завершении AJAX-запроса. Переменные события доступны через объект <code>event.detail</code>.</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;app:update-profile&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token parameter">event</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token function">alert</span><span class="token punctuation">(</span><span class="token string">&#39;Profile updated with name: &#39;</span> <span class="token operator">+</span> event<span class="token punctuation">.</span>detail<span class="token punctuation">.</span>name<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Например, если вы хотите показать предупреждение о том, что документ уже был обновлён другим пользователем, вы можете отправить событие в браузер и сгенерировать <code>AjaxException</code> для остановки процесса.</p><div class="custom-block tip"><p><code>AjaxException</code> и <code>ValidationException</code> — это останавливающие исключения, поддерживающие отправку событий.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onUpdate</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">dispatchBrowserEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;app:stale-document&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">AjaxException</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div></div><p>Вы можете прослушивать это событие в браузере с помощью универсального слушателя. Этот пример запрашивает подтверждение пользователя перед повторной отправкой запроса с флагом <code>force</code> в данных.</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;app:stale-document&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token parameter">event</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token function">confirm</span><span class="token punctuation">(</span><span class="token string">&#39;Another user has updated this document, proceed?&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        oc<span class="token punctuation">.</span><span class="token function">request</span><span class="token punctuation">(</span>event<span class="token punctuation">.</span>target<span class="token punctuation">,</span> <span class="token string">&#39;onUpdate&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">data</span><span class="token operator">:</span> <span class="token punctuation">{</span>
            <span class="token literal-property property">force</span><span class="token operator">:</span> <span class="token boolean">true</span>
        <span class="token punctuation">}</span><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Чтобы предотвратить обновление фрагментов в рамках ответа, вызовите <code>preventDefault()</code> на объекте события.</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;app:stale-document&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token parameter">event</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    event<span class="token punctuation">.</span><span class="token function">preventDefault</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div>`,58))])}const A=o(i,[["render",k]]);export{f as __pageData,A as default};
